### 4.5 Offline Support

```typescript
// client/offline-sync.ts

/**
 * Offline-first architecture using y-indexeddb + operation queue
 * 
 * User goes offline → keep editing → reconnect → auto-merge
 * No conflicts because CRDT! The merge is mathematically correct.
 */

import { IndexeddbPersistence } from 'y-indexeddb'
import { WebsocketProvider } from 'y-websocket'

class OfflineSyncManager {
  private ydoc: Y.Doc
  private localDb: IndexeddbPersistence
  private wsProvider: WebsocketProvider | null = null
  private pendingUpdates: Uint8Array[] = []
  private isOnline = navigator.onLine

  // Track what we've synced for differential sync on reconnect
  private lastSyncedStateVector: Uint8Array | null = null

  async initialize(docId: string, userId: string): Promise<void> {
    this.ydoc = new Y.Doc({ guid: docId })

    // CRITICAL: Initialize IndexedDB first
    // This loads any locally-saved state BEFORE connecting to server
    this.localDb = new IndexeddbPersistence(docId, this.ydoc)
    await this.localDb.whenSynced

    // Capture what we have locally
    this.lastSyncedStateVector = Y.encodeStateVector(this.ydoc)

    // Listen to local changes (from this session)
    this.ydoc.on('update', (update: Uint8Array, origin: string) => {
      if (origin !== 'server') {  // Don't re-queue server updates
        this.handleLocalUpdate(update)
      }
    })

    // Network status management
    window.addEventListener('online', () => this.handleOnline())
    window.addEventListener('offline', () => this.handleOffline())

    if (this.isOnline) {
      await this.connectWebSocket(docId, userId)
    }
  }

  private async connectWebSocket(docId: string, userId: string): Promise<void> {
    this.wsProvider = new WebsocketProvider(
      `wss://collab.example.com`,
      docId,
      this.ydoc,
      {
        connect: true,
        // Send our current state vector on connect
        // Server sends ONLY the diff we're missing
        params: { userId, token: await this.getAuthToken() }
      }
    )

    this.wsProvider.on('status', ({ status }: { status: string }) => {
      if (status === 'connected') {
        this.handleReconnected()
      }
    })

    this.wsProvider.on('sync', (isSynced: boolean) => {
      if (isSynced) {
        this.lastSyncedStateVector = Y.encodeStateVector(this.ydoc)
        this.onFullySynced()
      }
    })
  }

  private handleLocalUpdate(update: Uint8Array): void {
    if (!this.isOnline || !this.wsProvider?.wsconnected) {
      // Queue for later
      this.pendingUpdates.push(update)
      this.saveOfflineQueue()  // Persist queue in case of crash

      this.showOfflineIndicator()
    }
    // If online, y-websocket handles sending automatically
  }

  private async handleReconnected(): Promise<void> {
    this.isOnline = true

    if (this.pendingUpdates.length > 0) {
      // Merge all pending updates into one
      const mergedUpdate = this.mergePendingUpdates()

      // Send to server (CRDT: server will merge correctly)
      this.wsProvider!.ws!.send(this.encodeUpdateMessage(mergedUpdate))

      this.pendingUpdates = []
      await this.clearOfflineQueue()
    }

    this.showOnlineIndicator()
    this.showSyncComplete()
  }

  private handleOffline(): void {
    this.isOnline = false
    this.showOfflineIndicator()
    this.showOfflineMessage(`
      You're offline. Your changes are saved locally 
      and will sync when you reconnect.
    `)
  }

  /**
   * Merge multiple pending updates into one efficient update
   * Reduces number of messages on reconnect
   */
  private mergePendingUpdates(): Uint8Array {
    if (this.pendingUpdates.length === 1) return this.pendingUpdates[0]

    const doc = new Y.Doc()
    if (this.lastSyncedStateVector) {
      // Start from last known synced state
      Y.applyUpdate(doc, Y.encodeStateAsUpdate(this.ydoc, this.lastSyncedStateVector))
    }
    this.pendingUpdates.forEach(update => Y.applyUpdate(doc, update))

    return Y.encodeStateAsUpdate(doc, this.lastSyncedStateVector ?? undefined)
  }

  /**
   * Persist offline queue across browser crashes
   */
  private async saveOfflineQueue(): Promise<void> {
    const serialized = this.pendingUpdates.map(u => Array.from(u))
    localStorage.setItem(
      `offline-queue:${this.ydoc.guid}`,
      JSON.stringify(serialized)
    )
  }

  async restoreOfflineQueue(): Promise<void> {
    const saved = localStorage.getItem(`offline-queue:${this.ydoc.guid}`)
    if (saved) {
      const serialized: number[][] = JSON.parse(saved)
      this.pendingUpdates = serialized.map(u => new Uint8Array(u))
    }
  }

  /**
   * Show conflict summary to users after sync
   * (CRDT has already resolved structurally, this is UX)
   */
  private showSyncComplete(): void {
    const changeCount = this.pendingUpdates.length
    if (changeCount > 0) {
      this.notify({
        type: 'success',
        message: `Synced ${changeCount} offline changes`,
        actions: [{ label: 'View History', onClick: () => this.openHistory() }]
      })
    }
  }
}
